/**
 * 负责蚀时狼妃状态构造、原槽同引用读取、玩家知识裁剪和纯反射目标选择。
 * 输入为原角色／历史、日次与请求目标，输出为原状态引用、独立知识 DTO 或原目标决策。
 * 本数据 owner 保持 Node Proxy／描述符拒绝和精确形状；反射回执、实际状态写权与生命／
 * 请求权限仍归夜机制，数据检查和字段可写声明不提交效果或授予许可。
 */
import type {
  ReflectionScope,
  TimeConsortChoice,
  TimeConsortState,
  TimeConsortReadState,
} from "@ai-werewolf-arena/game-contract";
import type { PlayerTimeConsortState } from "@ai-werewolf-arena/game-contract/facts/time-consort";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const TIME_CONSORT_ROLE = "time_wolf_consort" as const;
export const TIME_CONSORT_POLICY = "awa_time_consort_reflection_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}

export function getTimeConsortState(
  role: RoleComponent | undefined,
): TimeConsortReadState | undefined {
  if (field(role, "role") !== TIME_CONSORT_ROLE || field(role, "camp") !== Camp.Wolf)
    return undefined;
  const state = field(field(role, "privateState"), "timeConsort");
  if (!exact(state, ["policy", "reflectionScope", "history", "triggeredDay"])) return undefined;
  const scope = field(state, "reflectionScope"),
    trigger = field(state, "triggeredDay");
  if (
    field(state, "policy") !== TIME_CONSORT_POLICY ||
    (scope !== "whole_night" && scope !== "first_effect") ||
    (trigger !== null && !integer(trigger))
  )
    return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  let previous = 0,
    previousTarget: number | null = null,
    triggerFound = trigger === null;
  for (const row of history) {
    if (!exact(row, ["day", "targetId"])) return undefined;
    const day = field(row, "day"),
      target = field(row, "targetId");
    if (
      !integer(day) ||
      day <= previous ||
      (target !== null && !integer(target)) ||
      (typeof trigger === "number" && day > trigger)
    )
      return undefined;
    if (target !== null && day === previous + 1 && target === previousTarget) return undefined;
    if (day === trigger) {
      if (target === null) return undefined;
      triggerFound = true;
    }
    previous = day;
    previousTarget = target as number | null;
  }
  if (!triggerFound) return undefined;
  return state as TimeConsortReadState;
}
export function createTimeConsortState(
  reflectionScope: ReflectionScope = "whole_night",
): TimeConsortState {
  return { policy: TIME_CONSORT_POLICY, reflectionScope, history: [], triggeredDay: null };
}
/** 自身知识投影：历史可见至观察 day，触发日严格早于 day 才告知耗尽。 */
export function projectTimeConsortState(
  role: RoleComponent | undefined,
  day: number,
): PlayerTimeConsortState | undefined {
  const state = getTimeConsortState(role);
  if (!state || !integer(day)) return undefined;
  const history: TimeConsortChoice[] = [];
  // 保留原 when<=day 的历史边界与逐行新副本；不能把耗尽的严格早于规则套到历史。
  for (const row of arrayItems(field(state, "history"))!) {
    const when = field(row, "day") as number;
    if (when > day) continue;
    history.push({ day: when, targetId: field(row, "targetId") as number | null });
  }
  const trigger = field(state, "triggeredDay") as number | null;
  return {
    policy: TIME_CONSORT_POLICY,
    reflectionScope: state.reflectionScope,
    history,
    exhausted: trigger !== null && trigger < day,
  };
}
/** 仅选择反射目标；真实效果归属、原体版本与付款／提交仍由夜回执复验。 */
export function timeConsortReflectionTarget(
  role: RoleComponent | undefined,
  day: number,
  sourceCamp: Camp,
  sourceId: number,
  requestedId: number,
  kind: string,
): number {
  if (!integer(day) || !integer(sourceId) || !integer(requestedId))
    throw new Error("time_consort_invalid_target");
  const state = getTimeConsortState(role);
  if (!state) throw new Error("time_consort_invalid_state");
  if (sourceCamp !== Camp.Good || !["check", "guard", "poison"].includes(kind)) return requestedId;
  const choice = arrayItems(field(state, "history"))!.find((h) => field(h, "day") === day);
  if (field(choice, "targetId") !== requestedId) return requestedId;
  if (
    state.triggeredDay !== null &&
    (state.triggeredDay !== day || state.reflectionScope === "first_effect")
  )
    return requestedId;
  return sourceId;
}

/**
 * 负责 蚀时狼妃 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { TIME_CONSORT_POLICY, createTimeConsortState, getTimeConsortState } from "./state";
import { timeConsortChoicePending, timeConsortChoiceTargets } from "./night_frame";
import { TIME_CONSORT_LOCK_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(TIME_CONSORT_POLICY).default(TIME_CONSORT_POLICY),
  reflectionScope: z.enum(["whole_night", "first_effect"]).default("whole_night"),
});
export const TIME_CONSORT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.TimeWolfConsort,
    camp: Camp.Wolf,
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.OrderPrince,
      Role.TimeWolfConsort,
    ],
    label: roleName("time_wolf_consort"),
    skillBrief: text("zh-CN", "role.time_wolf_consort.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.timeConsort ?? {});
      role.privateState.timeConsort = createTimeConsortState(value.reflectionScope);
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, timeConsort: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.timeConsort ?? {}),
    },
    toolSpecs: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs ?? []),
      {
        name: "lock_time",
        parameters: {
          type: "object",
          properties: {
            target_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["target_id", "abstain"],
          additionalProperties: false,
        },
        argHint: 'lock_time args: {"target_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.lock_time.hint",
      },
    ],
    stageDirectives: [
      ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives ?? []),
      {
        match: (tools) => tools.length === 1 && tools[0] === "lock_time",
        messageKey: "action.lock_time.directive",
        text: text("zh-CN", "action.lock_time.directive"),
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      lock_time: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getTimeConsortState(role) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "lock_time" ||
          !timeConsortChoicePending(world, actorId, day)
        )
          return { code: RuleError.TimeConsortUnavailable };
        const { target_id, abstain } = toolCall.args;
        if (abstain) return target_id === null ? null : { code: RuleError.TimeConsortTarget };
        return target_id !== null && timeConsortChoiceTargets(world, day).includes(target_id)
          ? null
          : { code: RuleError.TimeConsortTarget };
      },
    },
    nightStages: [TIME_CONSORT_LOCK_STAGE, ...(ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages ?? [])],
    baselineAction: (role, request, pick, pickCamp, locale, world) => {
      if (!request.allowedTools.includes("lock_time") || !world || !getTimeConsortState(role))
        return (
          ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pick,
            pickCamp,
            locale,
            world,
          ) ?? null
        );
      const targets = timeConsortChoiceTargets(world, request.context.day);
      return targets.length >= 1
        ? {
            name: "lock_time",
            args: { target_id: targets[0]!, abstain: false },
          }
        : { name: "lock_time", args: { target_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("time_wolf_consort"),
};

/**
 * Owns Time Consort target locks and their reflected night-action receipts. Inputs are original
 * players, the lock choice and native action kind; outputs are effective-target mappings and
 * currentness checks. Close/abort ends the lock night without transferring its effect to revived
 * targets.
 */
import type { TimeConsortState, TimeConsortReadState } from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { COMPONENT, Camp, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getTimeConsortState, projectTimeConsortState, TIME_CONSORT_ROLE } from "./state";

interface OriginalPlayer {
  abilityAuthority: () => boolean;
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  targetId: number | null;
  revision: number;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: TimeConsortReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function stateIdentity(role: RoleComponent): string {
  const view = projectTimeConsortState(role, Number.MAX_SAFE_INTEGER - 1);
  if (!view) throw new Error("time_consort_original_state_revoked");
  return JSON.stringify({ ...view, triggeredDay: getTimeConsortState(role)!.triggeredDay });
}
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}

const missingAbilityField = Symbol("missing_ability_field");
function boundAbilityData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value))
    throw new Error("time_consort_original_abilities_invalid");
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor) {
    if (key in value) throw new Error("time_consort_original_abilities_invalid");
    return missingAbilityField;
  }
  if (!("value" in descriptor)) throw new Error("time_consort_original_abilities_invalid");
  return descriptor.value;
}
function bindAbilities(role: RoleComponent): () => boolean {
  const container = boundAbilityData(role.privateState, "abilities");
  const prototype = Object.getPrototypeOf(role.privateState);
  if (container === missingAbilityField || container === undefined)
    return () =>
      Object.getPrototypeOf(role.privateState) === prototype &&
      boundAbilityData(role.privateState, "abilities") === container;
  if (
    !container ||
    typeof container !== "object" ||
    types.isProxy(container) ||
    Array.isArray(container)
  )
    throw new Error("time_consort_original_abilities_invalid");
  const names = Reflect.ownKeys(container);
  const bindings = names.map((key) => {
    const ability = ownData(container, key);
    if (!ability || typeof ability !== "object" || types.isProxy(ability))
      throw new Error("time_consort_original_abilities_invalid");
    const fields = [
      "id",
      "kind",
      "activation",
      "source",
      "state",
      "startsOnDay",
      "expiresAfterDay",
      "maxUses",
      "disabled",
      "deathExpired",
      "sourceDisclosed",
    ] as const;
    const values = fields.map((k) => boundAbilityData(ability, k)),
      source = ownData(ability, "source"),
      state = ownData(ability, "state");
    const sourceFields = ["kind", "role", "actorId", "abilityId"] as const,
      sourceValues = sourceFields.map((k) => boundAbilityData(source, k));
    const policyFields = [
        "targetPolicy",
        "actionPolicy",
        "selfHealRule",
        "knifeVisibility",
        "potionPolicy",
        "repeatPolicy",
      ] as const,
      policies = policyFields.map((k) => boundAbilityData(state, k));
    return () =>
      ownData(container, key) === ability &&
      fields.every((k, i) => boundAbilityData(ability, k) === values[i]) &&
      sourceFields.every((k, i) => boundAbilityData(source, k) === sourceValues[i]) &&
      policyFields.every((k, i) => boundAbilityData(state, k) === policies[i]);
  });
  return () =>
    Object.getPrototypeOf(role.privateState) === prototype &&
    boundAbilityData(role.privateState, "abilities") === container &&
    Reflect.ownKeys(container).length === names.length &&
    bindings.every((fn) => fn());
}

function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    !p.abilityAuthority() ||
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("time_consort_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("time_consort_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getTimeConsortState(actor.role) !== b.state || stateIdentity(actor.role) !== b.expectedState)
    throw new Error("time_consort_original_state_revoked");
  return b;
}
export function installTimeConsortBoard(world: World): void {
  if (boards.has(world)) throw new Error("time_consort_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: TimeConsortReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("time_consort_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("time_consort_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("time_consort_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("time_consort_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      abilityAuthority: bindAbilities(role),
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === TIME_CONSORT_ROLE) {
      if (actorId !== null) throw new Error("time_consort_original_roster_invalid");
      actorId = id;
      state = getTimeConsortState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0 || state.triggeredDay !== null)
    throw new Error("time_consort_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: stateIdentity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isTimeConsortBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}

export function beginTimeConsortNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("time_consort_night_invalid");
  const previous = projectTimeConsortState(b.players.get(b.actorId)!.role, day)!.history.at(-1);
  const targets = new Map(
    [...b.players].filter(
      ([id, p]) => p.life.alive && !(previous?.day === day - 1 && previous.targetId === id),
    ),
  );
  const eligible =
    b.players.get(b.actorId)!.life.alive && b.state.triggeredDay === null && targets.size > 0;
  b.night = { day, closed: false, committed: !eligible, targetId: null, targets, revision: 0 };
  return eligible ? b.actorId : null;
}
export function timeConsortChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  return !n || n.day !== day || n.closed || n.committed
    ? []
    : [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitTimeConsortChoice(
  world: World,
  actorId: number,
  day: number,
  targetId: number | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("time_consort_choice_scope_invalid");
  if (
    targetId !== null &&
    (!Number.isSafeInteger(targetId) || !n.targets.get(targetId)?.life.alive)
  )
    throw new Error("time_consort_choice_target_invalid");
  Object.defineProperty(b.state.history, String(b.state.history.length), {
    value: { day, targetId },
    writable: true,
    enumerable: true,
    configurable: true,
  });
  n.targetId = targetId;
  n.committed = true;
  n.revision++;
  b.expectedState = stateIdentity(b.players.get(actorId)!.role);
}
export interface TimeConsortReceipt {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly reflected: boolean;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
  readonly commit: () => void;
}
export function resolveTimeConsortTarget(
  world: World,
  day: number,
  sourceId: number,
  requestedId: number,
  kind: "check" | "guard" | "poison" | "heal" | "kill",
): TimeConsortReceipt {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("time_consort_night_unsettled");
  const source = b.players.get(sourceId),
    requested = b.players.get(requestedId);
  if (!source?.life.alive || !requested?.life.alive) throw new Error("time_consort_target_invalid");
  const reflected =
    source.camp === Camp.Good &&
    ["check", "guard", "poison"].includes(kind) &&
    n.targetId === requestedId &&
    (b.state.triggeredDay === null ||
      (b.state.triggeredDay === day && b.state.reflectionScope === "whole_night"));
  const effective = reflected ? source : requested;
  const sourceVersion = aliveLifeVersion(source.life),
    requestedVersion = aliveLifeVersion(requested.life),
    revision = n.revision;
  const scope: NightLifeScope = Object.freeze({
    id: effective.id,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  let used = false;
  const current = () => {
    try {
      return (
        !used &&
        requireBoard(world) === b &&
        b.night === n &&
        !n.closed &&
        n.committed &&
        n.revision === revision &&
        source.life.alive &&
        requested.life.alive &&
        effective.life.alive &&
        aliveLifeVersion(source.life) === sourceVersion &&
        aliveLifeVersion(requested.life) === requestedVersion &&
        aliveLifeVersion(effective.life) === scope.version
      );
    } catch {
      return false;
    }
  };
  return Object.freeze({
    requestedId,
    effectiveId: effective.id,
    reflected,
    scope,
    isCurrent: current,
    commit: () => {
      if (!current()) throw new Error("time_consort_receipt_stale");
      used = true;
      if (reflected) {
        (b.state as Pick<TimeConsortState, "triggeredDay">).triggeredDay = day;
        n.revision++;
        b.expectedState = stateIdentity(b.players.get(b.actorId)!.role);
      }
    },
  });
}
export function closeTimeConsortNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed)
    throw new Error("time_consort_night_unsettled");
  n.closed = true;
}
export function abortTimeConsortNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) n.closed = true;
}
export function assertTimeConsortRosterCurrent(world: World): void {
  requireBoard(world);
}
export function timeConsortChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}
export function timeConsortActorId(world: World): number | null {
  return boards.has(world) ? requireBoard(world).actorId : null;
}

/**
 * Executes the Time Consort lock request before affected native actions. Inputs are the bound
 * night frame and validated target choice; outputs are the committed lock fact. It does not move
 * reflection or paid-effect commitment ahead of the later native action owners.
 */
import type { AliveComponent } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getTimeConsortState } from "./state";
import {
  timeConsortActorId,
  assertTimeConsortRosterCurrent,
  beginTimeConsortNight,
  commitTimeConsortChoice,
  timeConsortChoiceTargets,
} from "./night_frame";
/** Runs from the configured role set, including after the time_consort's death. */
export const TIME_CONSORT_LOCK_STAGE: NightStageHandler = {
  id: "time_consort_lock",
  priority: 50,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginTimeConsortNight(ctx.world, day);
    if (actorId === null) {
      const id = timeConsortActorId(ctx.world);
      if (id === null) throw new Error("time_consort_actor_missing");
      const reason = ctx.world.getComponent(id, COMPONENT.Alive)!.alive ? "exhausted" : "dead";
      ctx.events.push({
        timestamp: Date.now(),
        type: "time_consort_lock_skipped",
        payload: { actorId: id, day, reason },
        audience: Object.freeze([id]),
      });
      return;
    }
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getTimeConsortState(role)) throw new Error("time_consort_actor_invalid");
    const request = ctx.makeRequest(actorId, ["lock_time"], {
      stage: "time_consort_lock",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      consort_candidates: timeConsortChoiceTargets(ctx.world, day),
    });
    assertTimeConsortRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertTimeConsortRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("time_consort_lock_stale");
    if (action?.name !== "lock_time") throw new Error("time_consort_lock_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertTimeConsortRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("time_consort_lock_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "lock_time")
      throw new Error("time_consort_lock_action_invalid");
    const args = validated.sanitizedCall.args;
    const targetId = args.abstain ? null : args.target_id!;
    commitTimeConsortChoice(ctx.world, actorId, day, targetId);
    ctx.events.push({
      timestamp: Date.now(),
      type: "time_consort_lock_committed",
      payload: {
        actorId,
        day,
        targetId,
      },
      audience: Object.freeze([actorId]),
    });
  },
};

